{
  "queries": [
    "\"Sublinear Preference Collapse\" RLHF reward models",
    "Kessler Mbeki 2024 RLHF reward model ICML",
    "\"Preference Collapse\" reward model RLHF paper"
  ],
  "numResults": 10
}

{
  "source": "crossref",
  "query": "Sublinear Preference Collapse in RLHF Reward Models",
  "limit": 10
}

{
  "command": "cd /tmp && curl -sL --max-time 60 https://proceedings.mlr.press/v235/ -o icml24.html; ls -la icml24.html; grep -io \"sublinear[^<]*\" icml24.html | head -20; echo \"---MBEKI---\"; grep -io \"mbeki[^<]*\" icml24.html | head; echo \"---PREF COLLAPSE---\"; grep -io \"[^<>]*preference collapse[^<>]*\" icml24.html | head",
  "timeout": 90
}

{
  "command": "cd /tmp && echo \"Kessler count:\"; grep -io \"kessler\" icml24.html | wc -l; echo \"titles containing reward model:\"; grep -io \"<a href=\\\"[^\\\"]*\\\"[^>]*>[^<]*[Rr]eward [Mm]odel[^<]*</a>\" icml24.html | sed 's/<[^>]*>//g' | head -30",
  "timeout": 30
}

{
  "command": "cd /tmp && echo \"author spans:\"; grep -c \"class=\\\"author\\\"\" icml24.html; echo \"reward hits:\"; grep -io \"reward\" icml24.html | wc -l; echo; grep -o \"<span class=\\\"author\\\">[^<]*</span>\" icml24.html | head -3; echo; grep -io \"<a href=\\\"[^\\\"]*\\.html\\\">[^<]*[Rr]eward[^<]*</a>\" icml24.html | sed 's/<[^>]*>//g' | head -20",
  "timeout": 30
}

{
  "command": "cd /tmp && grep -n -i \"reward\" icml24.html | head -5 | cut -c1-400; echo \"===\"; sed -n '1,40p' icml24.html | cut -c1-300",
  "timeout": 30
}

{
  "command": "cd /tmp && curl -sL --max-time 60 \"http://export.arxiv.org/api/query?search_query=ti:%22reward%20collapse%22&max_results=20\" -o rc.xml; grep -E \"<title>|<id>http|<name>|<published>\" rc.xml | sed 's/^ *//' | head -60",
  "timeout": 90
}

{
  "command": "cd /tmp && curl -sL --max-time 60 "http://export.arxiv.org/api/query?id_list=2305.17608" -o one.xml; python3 - <<'EOF'
import re
s=open('one.xml').read()
for tag in ['title','summary','arxiv:comment','published','arxiv:doi','arxiv:journal_ref']:
    m=re.findall(rf'<{tag}[^>]*>(.*?)</{tag}>',s,re.S)
    for x in m[:2]: print(tag.upper(),':',re.sub(r'\s+',' ',x).strip()[:900])
EOF",
  "timeout": 90
}

{
  "command": "cd /tmp && echo \"papers:\"; grep -c '<div class=\"paper\">' icml24.html; echo \"Mbeki:\"; grep -ic \"mbeki\" icml24.html; echo \"Kessler:\"; grep -ic \"kessler\" icml24.html; echo \"Sublinear Preference:\"; grep -ic \"sublinear preference\" icml24.html",
  "timeout": 30
}

